   423  internal_function
   424  __libelf_set_rawdata (Elf_Scn *scn)
   425  {
   426    int result;
   427
   428    if (scn == NULL)
   429      return 1;
   430
   431    rwlock_wrlock (scn->elf->lock);
   432    result = __libelf_set_rawdata_wrlock (scn);
