   438  void
   439  internal_function
   440  __libelf_set_data_list_rdlock (Elf_Scn *scn, int wrlocked)
   441  {
   442    if (scn->rawdata.d.d_buf != NULL && scn->rawdata.d.d_size > 0)
   443      {
   444        Elf *elf = scn->elf;
   445
   446        /* Upgrade the lock to a write lock if necessary and check
   447           nobody else already did the work.  */
   448        if (!wrlocked)
   449          {
   450            rwlock_unlock (elf->lock);
   451            rwlock_wrlock (elf->lock);
   452            if (scn->data_list_rear != NULL)
   453              return;
   454          }
   455
   456        /* Convert according to the version and the type.   */
   457        convert_data (scn, elf->class,
   458                      (elf->class == ELFCLASS32
   459                       || (offsetof (struct Elf, state.elf32.ehdr)
   460                           == offsetof (struct Elf, state.elf64.ehdr))
   461                       ? elf->state.elf32.ehdr->e_ident[EI_DATA]
   462                       : elf->state.elf64.ehdr->e_ident[EI_DATA]),
   463                      scn->rawdata.d.d_size, scn->rawdata.d.d_type);
   464      }
   465    else
   466      {
   467        /* This is an empty or NOBITS section.  There is no buffer but
   468           the size information etc is important.  */
   469        scn->data_list.data.d = scn->rawdata.d;
   470        scn->data_list.data.s = scn;
   471      }
   472
   473    scn->data_list_rear = &scn->data_list;
   474  }
