   573  Elf_Data *
   574  elf_getdata (Elf_Scn *scn, Elf_Data *data)
   575  {
   576    Elf_Data *result;
   577
   578    if (scn == NULL)
   579      return NULL;
   580
   581    rwlock_rdlock (scn->elf->lock);
   582    result = __elf_getdata_rdlock (scn, data);
   583    rwlock_unlock (scn->elf->lock);
   584
   585    return result;
   586  }
